Given the root of a binary tree, find the top view of the tree.The top view of a binary tree represents the set of nodes visible when the tree is viewed from above.Each node in the tree has a horizontal distance (HD) from the root, which helps determine its position when viewed from the top:The root node has an HD of 0.The left child of a node has an HD equal to parent’s HD - 1.The right child of a node has an HD equal to parent’s HD + 1.Note:The result should contain the nodes visible from leftmost to rightmost and if two nodes have the same horizontal distance, only the uppermost (first encountered) node should be considered in the top view.Examples:Input: Output: [2, 1, 3]Explanation: The Green colored nodes represents the top view in the below Binary tree.  Input:  Output: [40, 20, 10, 30, 100]Explanation: The Green colored nodes represents the top view in the below Binary tree.  Try It YourselfTable of Content[Approach 1] Using DFS - O(n * log n) Time and O(n) Space[Approach 2] Using BFS - O(n * log n) Time and O(n) Space[Optimized Approach] Using BFS - O(n) Time and O(n) Space[Approach 1] Using DFS - O(n * log n) Time and O(n) SpaceThe idea is to use a Depth-First Search (DFS) approach to find the top view of a binary tree. We keep track of horizontal distance from root node. Start from the root node with a distance of 0. When we move to left child we subtract 1 and add 1 when we move to right child to distance of the current node. We use a HashMap to store the top most node that appears at a given horizontal distance. As we traverse the tree, we check if there is any node at current distance in hashmap. If it's the first node encountered at its horizontal distance ,we include it in the top view.
            C++

    #include <iostream>
#include<vector>
#include<map>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int val) {
        data = val;
        left = right = nullptr;
    }
};

// DFS Helper to store top view nodes
void dfs(Node* node, int hd, int level, 
         map<int, pair<int, int>>& topNodes) {

    if (!node) return;

    // If horizontal distance is encountered for 
    // the first time or if it's at a higher level
    if (topNodes.find(hd) == topNodes.end() || 
        topNodes[hd].second > level) {
        topNodes[hd] = {node->data, level};
    }

    // Recur for left and right subtrees
    dfs(node->left, hd - 1, level + 1, topNodes);
    dfs(node->right, hd + 1, level + 1, topNodes);
}

// Finding the top view of a binary tree
vector<int> topView(Node* root) {
    vector<int> result;
    if (!root) return result;

    // Horizontal distance -> {node's value, level}
    map<int, pair<int, int>> topNodes; 

    // Start DFS traversal
    dfs(root, 0, 0, topNodes);

    // Collect nodes from the map
    for (auto it : topNodes) {
        result.push_back(it.second.first);
    }

    return result;
}


int main() {

  // Create a sample binary tree
  //     10
  //    /  \
  //   20   30
  //  / \   / \
  // 40  60 90  100

    Node* root = new Node(10);
    root->left = new Node(20);       
    root->right = new Node(30);            
    root->left->left = new Node(40);     
    root->left->right = new Node(60);   
    root->right->left = new Node(90);   
    root->right->right = new Node(100); 

    vector<int> result = topView(root);
    for (int i : result) {
        cout << i << " ";
    }
    return 0;
}


